"OLAYLAR_2S_0919:1399-02-13:0":{"b": ["गेरार्दो आप्पियानी ने पीसा विस्कोंती को सौंपा, पियोम्बीनो सेन्योरी की स्थापना की", "ac45a9dd"], "d": ["पीसा के सेन्योर गेरार्दो आप्पियानी ने नगर को 2,00,000 फ़्लोरिन में मिलान के शासक जान गालेआत्सो विस्कोंती को सौंप दिया। उसने पियोम्बीनो, सुवेरेतो, स्कार्लीनो तथा एल्बा, पियानोसा और मोंतेक्रिस्तो द्वीपों से बनी पियोम्बीनो सेन्योरी अपने लिए रखी।", "68084c1c"]},
"OLAYLAR_2S_0919:1401-01-01:0":{"b": ["दियारबक़िर क़ारायुलुक उस्मान बे को दिया गया — आक़कोयुनलू आधिपत्य आरंभ हुआ", "38262401"], "d": ["तैमूर द्वारा 1394 में जीता दियारबक़िर 1401 में क़ारायुलुक उस्मान बे को दिया गया और इस प्रकार क्षेत्र में आक़कोयुनलू आधिपत्य आरंभ हुआ।", "de407b9c"]},
"OLAYLAR_2S_0919:1410-01-01:0":{"b": ["एरज़िनजान क़राक़ोयुनलू आधिपत्य में आया", "5729a50b"], "d": ["मुताहर्तेन के बाद एरज़िनजान क़राक़ोयुनलू शासक क़ारा यूसुफ़ के हाथ आया। क़ारा यूसुफ़ ने नगर में पहले अपने विश्वस्त लोगों में से पीर ओमर को गवर्नर नियुक्त किया।", "69ef181d"]},
"OLAYLAR_2S_0919:1494-01-01:0":{"b": ["अस्किया मुहम्मद ने ज़ाग़ा (दिया) लिया", "24561a8c"], "d": ["सोंग्हाई सिंहासन पर बैठे अस्किया मुहम्मद ने हिजरी 899 के अंत में भाई कुर्मिना-फ़ारी अमर कोमज़ाग़ो के माध्यम से नाइजर के आंतरिक डेल्टा के पश्चिम के ज़ाग़ा (दिया) नगर पर अधिकार किया।", "f6d242d2"]},
"OLAYLAR_2S_0919:1500-01-01:0":{"b": ["शैबानी ख़ान ने बुख़ारा और समरकंद लिए", "8f8f40eb"], "d": ["मुहम्मद शैबानी ख़ान ने तैमूरियों के बीच की अराजकता का लाभ उठाकर बुख़ारा और समरकंद लिए और शैबानी (उज़्बेक) राजवंश की स्थापना की। 1500-1507 के बीच उन्होंने मावराउन्नहर, ख़्वारज़्म और ख़ुरासान के लगभग सभी नगर जीत लिए।", "0e64ecae"]},
"OLAYLAR_2S_0919:1510-01-01:0":{"b": ["स्पेनियों ने बिजाया पर क़ब्ज़ा किया", "8faa0133"], "d": ["जहाज़ों से आई 8000 की स्पेनी सेना ने बिजाया पर क़ब्ज़ा किया; नगर की जनता घबराकर अपनी भूमि छोड़ गई।", "364b6234"]},
"OLAYLAR_2S_0919:1515-01-01:0":{"b": ["अगादेज़ सोंग्हाई से जुड़ा", "997362b0"], "d": ["आयर क्षेत्र का केंद्र अगादेज़ सोंग्हाई सुल्तान अस्किया मुहम्मद द्वारा गाओ से जोड़ा गया; नगर सोंग्हाई के 1591 में तोंदिबी में पतन तक इस अधीनता में रहा।", "b2b437a3"]},
"OLAYLAR_2S_0919:1522-01-01:0":{"b": ["बागिर्मी सल्तनत की स्थापना हुई", "03829f94"], "d": ["केंगा क़बीले ने बिर्नी बेसी के नेतृत्व में चाड झील के पूर्व में मासिन्या (मासेन्या) केंद्र वाला शक्तिशाली राज्य स्थापित किया। बागिर्मी राजवंश की स्थापना परंपरागत रूप से 1522 की मानी जाती है।", "2bd4497c"]},
"OLAYLAR_2S_0919:1535-11-01:0":{"b": ["अंतिम स्फ़ोर्त्सा ड्यूक मरा, मिलान कार्ल पंचम को गया", "53230b5c"], "d": ["मिलान के ड्यूक फ़्रांचेस्को द्वितीय स्फ़ोर्त्सा की 1-2 नवंबर 1535 की रात निःसंतान मृत्यु हुई। डची सम्राट कार्ल पंचम को गई और एक स्पेनी गवर्नर द्वारा शासित होने लगी।", "03b908c5"]},
"OLAYLAR_2S_0919:1544-01-01:0":{"b": ["जेनोआई ताबारका द्वीप में बसे", "0cb474f8"], "d": ["कार्ल पंचम के ट्यूनिस के शासक से किए गए, तट पर क़िला बनाने और मूँगा पकड़ने की अनुमति देने वाले समझौते पर पेग्ली का एक जेनोआई समुदाय ताबारका द्वीप में बसाया गया। द्वीप लोमेल्लीनी परिवार द्वारा शासित व्यापारिक अड्डा बना।", "74c7ab83"]},
"OLAYLAR_2S_0919:1556-01-01:0":{"b": ["हुमायूँ की मृत्यु के बाद सफ़ावियों ने क़ंदहार बाबुरियों से लिया", "318eabc8"], "d": ["हुमायूँ की 1556 में दिल्ली में मृत्यु के बाद शाह तहमास्प ने क़ंदहार और ज़मींदावर के बाबुरी गवर्नरों के बीच के विवाद का लाभ उठाया; ज़मींदावर के गवर्नर के निमंत्रण पर आई एक सफ़ावी टुकड़ी क़ंदहार में प्रविष्ट हुई और तहमास्प ने चचेरे भाई सुल्तान हुसैन मिर्ज़ा को नगर का गवर्नर नियुक्त किया। नगर 1595 तक सफ़ावी हाथ में रहा।", "87ac27f5"]},
"OLAYLAR_2S_0919:1558-01-01:0":{"b": ["रूस ने लिवोनिया पर आक्रमण किया, डोरपाट गिरा", "dcb46a8a"], "d": ["इवान चतुर्थ ने बाल्टिक तक पहुँचने के लिए लिवोनिया पर आक्रमण कर लिवोनियाई युद्ध आरंभ किया; नारवा और डोरपाट (तार्तू) को जीतकर रेवल को घेरा।", "37f1dd66"]},
